(function(){
  var NAMES=['分','时','日','月','周'];
  var MAX=[59,23,31,12,6];
  function parseField(f,max){
    if(f==='*') return {any:true, ok:true};
    var parts=f.split(','), set={}, step=1, ok=true;
    parts.forEach(function(p){
      var m=p.match(/^(\*|\d+(?:-\d+)?)(?:\/(\d+))?$/);
      if(!m){ ok=false; return; }
      var range=m[1], st=m[2]?parseInt(m[2],10):1;
      var lo,hi; if(range==='*'){lo=0;hi=max;} else if(range.indexOf('-')>=0){var a=range.split('-');lo=+a[0];hi=+a[1];} else lo=hi=+range;
      if(lo<0||hi>max||lo>hi){ok=false;return;}
      for(var i=lo;i<=hi;i+=st){ set[i]=1; }
    });
    return {ok:ok,set:set};
  }
  function explain(fields){
    if(fields.length!==5) return {error:'需要 5 段表达式'};
    var labels=['每分钟','每小时','每天','每月','每周'];
    var res=[];
    for(var i=0;i<5;i++){ var f=parseField(fields[i],MAX[i]); if(!f.ok) return {error:'第'+(i+1)+'段「'+fields[i]+'」非法（'+NAMES[i]+'范围 0-'+MAX[i]+'）'};
      if(f.any) res.push(labels[i]); else res.push(NAMES[i]+' '+Object.keys(f.set).map(Number).sort(function(a,b){return a-b;}).join('/')); }
    return {value:res.join('，')};
  }
  function match(fields,dt){
    for(var i=0;i<5;i++){ var f=parseField(fields[i],MAX[i]); if(!f.any && !f.set[ [dt.getMinutes(),dt.getHours(),dt.getDate(),dt.getMonth()+1,dt.getDay()][i] ]) return false; }
    return true;
  }
  function next(expr,fromIso,n){
    var fields=String(expr).trim().split(/\s+/); if(fields.length!==5) return {error:'需要 5 段表达式'};
    for(var i=0;i<5;i++){ var f=parseField(fields[i],MAX[i]); if(!f.ok) return {error:'第'+(i+1)+'段非法'}; }
    var dt=fromIso? new Date(fromIso): new Date(); dt.setSeconds(0,0);
    var out=[], guard=0;
    while(out.length<n && guard<4*366*24*60){ if(match(fields,dt)){ out.push(dt.toISOString().replace(/\.\d+Z$/,'Z')); dt.setMinutes(dt.getMinutes()+1); }
      else { dt.setMinutes(dt.getMinutes()+1); } guard++; }
    if(out.length===0) return {error:'未来 4 年内未匹配'};
    return {value:out.join('\n')};
  }
  var API={explain:explain,next:next};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__CrontabForge__=API;
})();
